use std::time::Duration;

/// A generated config older than this is regenerated by `vpnlane up`.
pub const MAX_CONF_AGE: Duration = Duration::from_hours(7 * 24);

/// Whether a config of this age should be regenerated. `None` means missing.
pub fn is_stale(conf_age: Option<Duration>) -> bool {
    conf_age.is_none_or(|age| age > MAX_CONF_AGE)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn missing_or_old_is_stale() {
        assert!(is_stale(None));
        assert!(is_stale(Some(MAX_CONF_AGE + Duration::from_secs(1))));
        assert!(!is_stale(Some(MAX_CONF_AGE)));
        assert!(!is_stale(Some(Duration::ZERO)));
    }

    // README, `up --help` and ARCHITECTURE promise 7 days: pin the literal.
    #[test]
    fn limit_is_seven_days() {
        assert_eq!(MAX_CONF_AGE, Duration::from_hours(168));
        assert!(!is_stale(Some(Duration::from_hours(6 * 24))));
        assert!(is_stale(Some(Duration::from_hours(8 * 24))));
    }
}
